  summary, body, image_url, image_credit, image_source, verification_json, source
) VALUES (
  'waterkloof-airshow-road-closures-centurion-2026-09-18',
  'Centurion roads near Waterkloof closed daily until Sunday for the aerospace show',
  'Traffic', '2026-09-18', 'The Citizen', 'https://www.citizen.co.za/news/these-roads-affected-closed-eff-march-africa-aerospace-defence-show-tshwane/',
  'Roads around Air Force Base Waterkloof in Centurion are shut from 4am to 4pm each day until Sunday 20 September for the Africa Aerospace and Defence show.',
  'Motorists around Centurion should expect closed roads near Air Force Base Waterkloof until the end of today, Sunday 20 September, while the Africa Aerospace and Defence show takes place at the base. The closures apply every day between 4am and 4pm, according to reports on the traffic plan.

Reported closures cover the Dastek intersection and Solomon Mahlangu Drive (including where it meets Union Avenue), plus Gate 2. Kruger Avenue is shut, as is Pierre van Ryneveld Avenue, and so is the R21 for southbound traffic. The show organisers also list the R21 and M10 junction, Veldpou Street near Dastek and the Trichardt Road and Kruger Avenue crossing as hard closures.

Drivers who do not need to pass the base are pointed towards alternatives: Trichardt Road, Veldpou Street, Nellmapius Drive (M31), Van Ryneveld Avenue (M27), Botha Avenue and Rigel Avenue.

Visitors heading to the show have alternatives to driving. Gautrain is running a free shuttle between Centurion Station and the base, and the organisers say the City of Tshwane operates park-and-ride pick-up points at the Centurion Gautrain station, the SAAF 68 Squadron site and Zwartkops Memorial on Snake Valley Road, and Armscor on Nossob Drive. Standard Gautrain fares still apply to train trips.',
  NULL, NULL, NULL,
  '["https://www.citizen.co.za/news/these-roads-affected-closed-eff-march-africa-aerospace-defence-show-tshwane/", "https://www.joburgetc.com/news/tshwane-traffic-eff-march-aad-friday-closures/", "https://www.aadexpo.co.za/visitors/public-visitors/venue-information", "https://htxt.co.za/2026/09/ride-the-rail-reach-for-the-skies-as-gautrain-teams-up-with-africa-aerospace-and-defence-expo-2026/"]',
  'agent'
);

INSERT OR IGNORE INTO news (
  slug, title, category, published_date, source_name, source_url,
  summary, body, image_url, image_credit, image_source, verification_json, source
) VALUES (
  'sundowns-beat-al-ahli-loftus-african-asian-pacific-cup-2026-09-19',
  'Sundowns beat Al Ahli at Loftus to win the African-Asian-Pacific Cup',
  'Sport', '2026-09-19', 'TimesLIVE', 'https://www.timeslive.co.za/sport/soccer/2026-09-19-sundowns-topple-al-ahli-to-lift-african-asian-pacific-cup/',
  'Mamelodi Sundowns beat Saudi side Al Ahli 2-1 at Loftus Versfeld on Saturday and go on to the next round of the FIFA Intercontinental Cup.',
  'Mamelodi Sundowns won the FIFA African-Asian-Pacific Cup on Saturday 19 September, beating Al Ahli of Saudi Arabia 2-1 in front of their home crowd at Loftus Versfeld in Pretoria.

Nuno Santos scored both goals for the South African side, each with a header. Al Ahli pulled level in the first half when a shot deflected off Sundowns goalkeeper Ronwen Williams and went in, but Santos restored the lead after the break.

The result sends Sundowns into the next stage of the FIFA Intercontinental Cup, where they meet the winner of the match between Mexico''s Toluca and the Copa Libertadores champions. According to the reports, whoever comes through that semifinal plays Paris Saint-Germain, the reigning European champions, in the final.',
  NULL, NULL, NULL,
  '["https://www.timeslive.co.za/sport/soccer/2026-09-19-sundowns-topple-al-ahli-to-lift-african-asian-pacific-cup/", "https://kawowo.com/2026/09/20/mamelodi-sundowns-edge-al-ahli-to-win-african-asian-pacific-cup-progress-in-fifa-intercontinental-cup/"]',
  'agent'
);
